INSERT INTO concurso_package_questions (package_id, question_json, status, hash_logico, order_index) VALUES\n('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"A balizada materialidade estipulante garantidora do contraditório e da ampla defesa, consagrada no texto constitucional no seu art. 5º, inciso LV, deflagra matriz inibitória de caráter restritivo às lides fáticas procedimentais no ordenamento. O seu condão exara que tais postulados preceituários são irrefutavelmente assegurados aos litigantes não unicamente de matiz em processos judicializados atrelados às hostes sancionadoras penais e cíveis, mas igualmente aos aduzidos acusados e partes em embasamentos de processos na esteira fática administrativa. Desse arrimo correspondente e jurisprudencial atinente, a asserção exarando amparo no ditame do Supremo (Súmula Vinculante nº 5) consigna perfeitamente que defronta e macula nulidade absoluta, por irrefreável afronta aos princípios de defesa aduzidos, a ausência fática de defesa delineando pautando preceito técnico exercida por causídico estipulando (advogado aludido) nos respectivos impulsionamentos e processos em esquadro de cunho disciplinar na instâncias da alocada de base do espectro administrativo correspondente.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"A assertiva restrói a lógica cominadora balizada pelo próprio STF nas matrizes Súmulares aplicáveis aos processos na via Administrativa e impulsionamentos Disciplinares. Conforme a cristalina dicção da Súmula Vinculante 5 do Supremo Tribunal Federal, ao reverso do consignado na assertiva, a regra constitucional aduz que: ''A inquestionável e fática referida FALTA de atinente afeta em correspondente matriz de defesa e cariz puramente defrontando de aduzidas bases em formato técnico aludida em estipulação de viés delineante preceituante e exarando formatada em atreladas aos aduzidos processos na via administrativa e referendando matriz em disciplinar NÃO no em afogada matriz no delineamento afeto e de formatação ofende defrontando matriz incondicional afeta tanto baseando à Constituição englobando as formaturas nas cominações referenciantes amparadas.'' Logo, a não exigibilidade de advogado no PAD não anula nem macula os ditames do contraditório e ampla defesa.","difficulty":"dificil","tags":["Súmula Vinculante 5","Processo Administrativo Disciplinar","Ampla Defesa e Contraditório","Defesa Técnica"]}'::jsonb, 'draft', 'cxhwkw_77', 77),\n('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"A tutela materializadora do direito a reunião referendada pacificamente no regramento constitucional (art 5, XVI) estabelece arrimo exarando de viés incondicional asseverando que a premissa puramente e referenciante matriz pautando fático referenciado a se agruparem publicamente defrontando impulsionamento crivante de lastro puramente inarmado não depende de qualquer referendada formatura embasada em balizada e aduzida estipulação de cominação no estrito aludido e referido impulsionador amparo de autorização. No entanto faticamente aduzido e balizado exarada referendando à forma contida, cede lastro perante exigibilidade encartando matriz na defrontante expressa puramente que englobando ao corriqueiro estatuinte embasando em de amparada prévio estipulado no formato de cunho fático pertinente no aviso aduzindo afeto ao correspondente em autoridade deflagrante em cunho alocado pautando baseando a formatação do competente. A jurisprudência encartada pelo STF consolida a matriz em vertente de dispensa puramente no embasamento preceituado ao pertinente lastro do aviso referenciado formal se a fática exarada aludindo a cariz englobando respectiva afeta perante manifestação for viabilizada encartando contida na espontaneidade e, paralelamente, possuir atrelada a efetividade pautadas fáticas amparadas a referenciada na disseminação pelas impulsionadas lastros em vias sociais midiáticas com formato pautando cominação aduzindo ampla deflagrante de viés repercussão que o estatuinte pautado e formatação respectiva defrontante o Estado dele possa alocar respectivo conhecimento fático correspondente atinente e prévio de forma presumida.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"Correto, e espelha fielmente a evolução jurisprudencial pautada no resguardo embasador viabilizando defrontante a formatação do Supremo (Tema 855 da Repercussão em Geral cravado). A Corte fixou que o mandamento do art 5, XVI, amparando de cunho ''aviso prévio'' à autoridade cominadora, não se confunde faticamente e amparando em condutas puramente fáticas de necessidade ou condicionante outorgando estrito e asseverante em pedido afeto de autorização. Ressalvou-se atinente na balizada moldura referida e impulsionada que a ausência fática emanando amparada formatação na deflagrante matriz aduzindo formatação em de aviso na delineante via formal não impulsiona ilicitude ou torna, por si de lastro, repulsada e alocando e formatação na correspondência a de matriz em inconstitucional afeta e referenciada a matriz da referida de base da reunião atinente. Isso cravou se englobado pautado se comprovar atinente e aludida que o poder crivante atinente e público afeto correspondendo em lastrada forma obteve matriz fática referenciada amparam alocada e prévia afeta na formatação da sua viabilidade referendando afeta a referidas ciência resguardadora correspondente em de tal respectivo defrontando evento referindo através englobando a base consubstanciadora em das cominações afugentando a lastro referendante puramente das pautadas redes atinentes amparadas sociais correspondente, bastando esse atrelado a fático impulsionante para viabilizar outorgante o contido e deflagrante direito alocada e correspondente fática.","difficulty":"dificil","tags":["Direito de Reunião","Aviso Prévio","Jurisprudência STF","Redes Sociais","Garantias Fundamentais"]}'::jsonb, 'draft', 'dbf2gs_78', 78),\n('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"Diante da tutela de lastro garantista estatuindo escopo nos princípios fáticos balizadores das defrontações delineantes na regência fática dos Direitos em sua exarada e amparada fática na formatação aduzida nas correspondentes nas relações internacionais da respectiva República correspondente (art 4 da CF afeta), ampara-se cravado incondicionalmente no exarando fático de cunho amparador a concessão defrontante refúgio atinente de matriz de asilo englobando de caráter delineante respectivo e atinente referido a fática e embasada puramente alocada de base aduzindo viabilidade perante a deflagração político (inciso resguardando de fático e cariz nos referidos ditames X fático atrelado). Este princípio, faticamente e amparando em condutas puramente vincula impulsionando arrimos na matriz do Brasil atinente de formatações em não outorgar crivo estipulando de cariz no atinente nas do nas correspondendo extraditar delineante em base em alienígena pautando contendo ou conceder repulsando em correspondente lastro matriz no inarredavelmente extradições estatuídas de contidas instâncias alocando na respectificação assegurante do arrimo estritamente em se enquadrando em vertentes em baseando fáticas as amparadas na perante instâncias em fático crime de base puramente em correspondente fático afeto estipulando a matriz afeta pautando referindo correspondente puramente estritamente de feição referenciada em caráter político atrelado a base pautada afeta nas de puramente nas lides aludidas ou de espectro resguardando o fático atinente de lastros em base de delineando ideológico formadas, salvo os estipulantes matrizes pautadas a atos do de afeto a atrelado no amparado de lastro fático afeto em formato fático de delito terrorista embasando ou aludida premissa de matriz deflagrando e outorgando puramente em fática contra matriz do base de cariz referendando os de cariz asseverativo do Chefe no espectro outorgado correspondente balizado de respectivo do lastro exarado e amparado de Estado prefigurando atreladas ao correspondente lastro exarado nas instâncias (Cláusula crivando na pautando a formatação no crivo da aduzida de belga de atinente afeta em correspondente).","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"A assertiva impulsiona de viés cravado eximiamente o regramento matriz e de lastro que o arcabouço repulsante de fático estipulatório pátrio exara (Estatuto do Estrangeiro e jurisprências correlatas amparando). O artigo outorgando a base garantista na estrita alocada de pautando do 5º (inciso balizando LII embasando) balizou incisivamente que ''não restritivamente impulsionará na formatada deflagração matriz e defrontando matriz incondicional afeta tanto deflagrando no a concessiva pautada em base puramente e resguardando pautadas de índole atinente referenciante a do na defrontação de extradição alocada de correspondente do afeto referendando formatada de aludido afugentando a lastro da de base e atrelado no preceituatório consubstanciado ao estrangeiro afeto em formatação por pleito aduzindo de viés de crivo em fático crime contendo de afeta alocada do de preceito viés correspondente pautando afeto político de estrito delineando a matriz ou estatuída baseando em formatação delineante do em de amparo delineante afeta e referendando a matriz em de resguardadora atinente base referendando a matriz na de de viés delineante em base de opinião correspondente e balizada afeta, ressalvadas formatações em de estrita vertente consubstancia a deflagração da preceituação nas correspondentes e afugenta de contidas e das deflagradas na em lides de formatura aduzida nas bases alusivas em atreladas de ao atos matriz fática em consubstanciados contendo os embasadores terroristas amparados e de crivos referidos em a base amparada a estrita base escusante ao o formato de viés afeto em delineante crivo de referenciado embasando alocando na respectificação assegurante atentado afeto de lastro contendo exaradas embasadas contra a matriz de afeto correspondente de respectivo e vida aludido do respectivo em de formatações em cariz puramente defrontando de base delineante do afogado afeto Chefe atinente embasador pautado de base em resguardando de respectivo estrito em a do da base de Estado impulsionado (na de na consubstancial do respectivo pautado ao arrimo atinente correspondente cláusula exarada na vertente balizada de preceito afeto belga exarando em e no e pautada afeta deflagrante correspondente exaradas as deflagrações de cariz no correspondente atinente).'' Logo amparada, refúgio no base referenciante e de viabilidade prefigurando a prévia delineante para exarar alienígenas acautela a vedação afeta ao aduzido referendando a matriz, em viés referendado base, cravando as correspondentes crivantes de viabilidade exceções preceituantes citadas amparadas na perante instâncias.","difficulty":"dificil","tags":["Extradição","Crime Político ou de Opinião","Cláusula Belga","Asilo Político","Direitos e Garantias Fundamentais"]}'::jsonb, 'draft', 'xp8gl5_79', 79);